Local Ltac lia ::= pe3_lia.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := U1Layout.
Abbreviation SEGS := Ubsan.M.loaded_segments.
Definition SN_NUL : Z := 0xdcfcc.

Section SnWrite.
  Context {fx : FPState}.

  Lemma sn_write0 : forall R M (sp ret f c cs cn k wbase fbuf : Z) bs,
    getr R 1%bv = Z_to_bv 64 ret -> ret_ok (Z_to_bv 64 ret) -> 0 <= ret < 2 ^ 64 ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 10%bv = Z_to_bv 64 f -> getr R 12%bv = Z_to_bv 64 0 ->
    2 ^ 16 <= sp - 64 -> sp < 2 ^ 47 -> sp mod 16 = 0 -> mdef M (sp - 64) 64 ->
    2 ^ 16 <= f -> f + 232 < 2 ^ 47 -> (f + 232 <= sp - 64 \/ sp <= f) -> mdef M f 232 ->
    fld SEGS M (f + 152) 8 c -> fld SEGS M (f + 40) 8 (wbase + k) -> fld SEGS M (f + 56) 8 wbase -> fld SEGS M (f + 88) 8 fbuf ->
    0 <= fbuf < 2 ^ 64 ->
    2 ^ 16 <= c -> c + 16 < 2 ^ 47 -> (c + 16 <= sp - 64 \/ sp <= c) -> (c + 16 <= f \/ f + 232 <= c) -> mdef M c 16 ->
    fld SEGS M c 8 cs -> fld SEGS M (c + 8) 8 cn ->
    1 <= k <= cn -> cn < 2 ^ 47 ->
    2 ^ 16 <= cs -> cs + k + 1 < 2 ^ 47 -> mdef M cs (k + 1) ->
    (cs + k + 1 <= sp - 64 \/ sp <= cs) -> (cs + k + 1 <= f \/ f + 232 <= cs) -> (cs + k + 1 <= c \/ c + 16 <= cs) ->
    2 ^ 16 <= wbase -> wbase + k < 2 ^ 47 -> rdn SEGS M (Z_to_bv 64 wbase) (Z.to_nat k) = Some bs ->
    (cs + k + 1 <= wbase \/ wbase + k <= cs) -> (wbase + k <= sp - 64 \/ sp <= wbase) ->
    exists R' M',
      msteps SEGS (@mkst fx R (Z_to_bv 64 A_SN_WRITE) M (seg_rom SEGS)) (@mkst fx R' (Z_to_bv 64 ret) M' (seg_rom SEGS))
      /\ getr R' 10%bv = Z_to_bv 64 0
      /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
      /\ stores_in (fun a => zwin (sp - 64) sp a \/ zwin cs (cs + k + 1) a \/ zwin c (c + 16) a \/ zwin (f + 40) (f + 48) a \/ zwin (f + 56) (f + 64) a) M M'
      /\ fld SEGS M' c 8 (cs + k) /\ fld SEGS M' (c + 8) 8 (cn - k)
      /\ fld SEGS M' (f + 40) 8 fbuf /\ fld SEGS M' (f + 56) 8 fbuf /\ fld SEGS M' (cs + k) 1 0
